const { execSync } = require('child_process');

// Clear out any leftover temp files from previous crashed runs
try {
  execSync('find /music/processing -type f -delete');
} catch(e) {}

// Find all MP3s in the input folder
let result;
try {
  result = execSync('find /music/input -name "*.mp3" -type f')
    .toString()
    .trim();
} catch(e) {
  result = '';
}

// If folder is empty, stop here quietly
if (!result) {
  return [];
}

const files = result.split('\n').filter(f => f.length > 0);

return files.map(filePath => ({
  json: { 
    filePath,
    fileName: filePath.split('/').pop(),
    status: 'queued'
  }
}));

const { execSync } = require('child_process');

const results = [];

for (const item of $input.all()) {
  const { filePath, fileName } = item.json;

  const timestamp = Date.now();
  const safeName = fileName.replace(/[^a-zA-Z0-9._-]/g, '_');
  const workingName = `${timestamp}_${safeName}`;
  const processingPath = `/music/processing/${workingName}`;

  try {
    // Copy, not move: the original stays in input/ until the run succeeds
    execSync(`cp "${filePath}" "${processingPath}"`);

    results.push({ json: {
      originalName: fileName,
      originalPath: filePath,
      workingName,
      processingPath,
      status: 'processing'
    }});

  } catch(e) {
    results.push({ json: {
      originalName: fileName,
      workingName,
      originalPath: filePath,
      processingPath,
      status: 'move_failed',
      error: e.message.substring(0, 200)
    }});
  }
}

return results;

const { execSync } = require('child_process');

const results = [];

for (const item of $input.all()) {
  const { processingPath, workingName, originalName } = item.json;
  const trimmedPath = `/music/processing/trimmed_${workingName}`;

  try {
    // Match the source bitrate, rounded up to a standard MP3 rate (max 320 kbps)
    let bitrate = 320;
    try {
      const probed = parseInt(execSync(`ffprobe -v error -select_streams a:0 -show_entries stream=bit_rate -of default=nw=1:nk=1 "${processingPath}"`).toString(), 10);
      if (probed > 0) bitrate = [32, 40, 48, 56, 64, 80, 96, 112, 128, 160, 192, 224, 256, 320].find(r => r * 1000 >= probed) || 320;
    } catch(e) {}

    execSync(`ffmpeg -i "${processingPath}" -af "silenceremove=start_periods=1:start_silence=0.1:start_threshold=-50dB:stop_periods=-1:stop_silence=0.1:stop_threshold=-50dB" -b:a ${bitrate}k "${trimmedPath}" -y 2>&1`);
    execSync(`rm -f "${processingPath}"`);

    results.push({ json: {
      originalName,
      workingName,
      processingPath: trimmedPath,
      status: 'trimmed'
    }});

  } catch(e) {
    try {
      execSync(`cp "${processingPath}" "${trimmedPath}"`);
      execSync(`rm -f "${processingPath}"`);
    } catch(e2) {}

    results.push({ json: {
      originalName,
      workingName,
      processingPath: trimmedPath,
      status: 'trim_skipped',
      trimError: e.message.substring(0, 200)
    }});
  }
}

return results;

const { execSync } = require('child_process');

const results = [];

for (const item of $input.all()) {
  const { processingPath, workingName, originalName } = item.json;

  let loudnormStats = null;

  try {
    const analysis = execSync(
      `ffmpeg -i "${processingPath}" -af loudnorm=I=-14:TP=-1:LRA=11:print_format=json -f null /dev/null 2>&1`
    ).toString();

    const jsonMatch = analysis.match(/\{[\s\S]*?"input_i"[\s\S]*?\}/);
    if (jsonMatch) {
      loudnormStats = JSON.parse(jsonMatch[0]);
    }
  } catch(e) {}

  results.push({ json: {
    originalName,
    workingName,
    processingPath,
    loudnormStats,
    status: loudnormStats ? 'analyzed' : 'analysis_skipped'
  }});
}

return results;

const { execSync } = require('child_process');

const results = [];

for (const item of $input.all()) {
  const { processingPath, workingName, originalName, loudnormStats } = item.json;
  const normalizedPath = `/music/processing/normalized_${workingName}`;

  try {
    // Match the source bitrate, rounded up to a standard MP3 rate (max 320 kbps)
    let bitrate = 320;
    try {
      const probed = parseInt(execSync(`ffprobe -v error -select_streams a:0 -show_entries stream=bit_rate -of default=nw=1:nk=1 "${processingPath}"`).toString(), 10);
      if (probed > 0) bitrate = [32, 40, 48, 56, 64, 80, 96, 112, 128, 160, 192, 224, 256, 320].find(r => r * 1000 >= probed) || 320;
    } catch(e) {}

    let filter;

    if (loudnormStats) {
      filter = `loudnorm=I=-14:TP=-1:LRA=11:measured_I=${loudnormStats.input_i}:measured_TP=${loudnormStats.input_tp}:measured_LRA=${loudnormStats.input_lra}:measured_thresh=${loudnormStats.input_thresh}:offset=${loudnormStats.target_offset}:linear=true`;
    } else {
      filter = `loudnorm=I=-14:TP=-1:LRA=11`;
    }

    execSync(`ffmpeg -i "${processingPath}" -af "${filter}" -b:a ${bitrate}k "${normalizedPath}" -y 2>&1`);
    execSync(`rm -f "${processingPath}"`);

    results.push({ json: {
      originalName,
      workingName,
      processingPath: normalizedPath,
      status: 'normalized'
    }});

  } catch(e) {
    try {
      execSync(`cp "${processingPath}" "${normalizedPath}"`);
      execSync(`rm -f "${processingPath}"`);
    } catch(e2) {}

    results.push({ json: {
      originalName,
      workingName,
      processingPath: normalizedPath,
      status: 'normalization_skipped',
      normError: e.message.substring(0, 200)
    }});
  }
}

return results;

const { execSync } = require('child_process');

const results = [];

for (const item of $input.all()) {
  const { processingPath, workingName, originalName } = item.json;

  let metadata = {
    title: '',
    artist: '',
    album: '',
    year: '',
    fingerprintStatus: 'not_attempted'
  };

  try {
    const fpcalcOutput = execSync(`fpcalc "${processingPath}"`).toString();

    const duration = fpcalcOutput.match(/DURATION=(\d+)/)?.[1];
    const fingerprint = fpcalcOutput.match(/FINGERPRINT=(.+)/)?.[1]?.trim();

    if (duration && fingerprint) {
      const response = execSync(
        `curl -s "https://api.acoustid.org/v2/lookup?client=YOUR_ACOUSTID_API_KEY&meta=recordings+releasegroups&duration=${duration}&fingerprint=${fingerprint}"`
      ).toString();

      const data = JSON.parse(response);

      if (data.status === 'ok' && data.results?.length > 0) {
        const recording = data.results[0].recordings?.[0];

        if (recording) {
          metadata.title = recording.title || '';
          metadata.artist = recording.artists?.[0]?.name || '';
          metadata.album = recording.releasegroups?.[0]?.title || '';
          metadata.year = recording.releasegroups?.[0]?.['first-release-date']?.substring(0, 4) || '';
          metadata.fingerprintStatus = 'matched';
        } else {
          metadata.fingerprintStatus = 'no_recording_found';
        }
      } else {
        metadata.fingerprintStatus = 'no_match';
      }
    }

    // Respect AcoustID rate limits
    execSync('sleep 1');

  } catch(e) {
    metadata.fingerprintStatus = 'error';
    metadata.fingerprintError = e.message.substring(0, 200);
  }

  results.push({ json: {
    originalName,
    workingName,
    processingPath,
    ...metadata,
    status: metadata.fingerprintStatus === 'matched' ? 'tagged' : 'untagged'
  }});
}

return results;

const { execSync } = require('child_process');

const results = [];

for (const item of $input.all()) {
  const { processingPath, originalName, workingName, title, artist, album, year, fingerprintStatus } = item.json;

  const outputPath = `/music/output/${originalName}`;

  try {
    let metaFlags = '';
    if (title)  metaFlags += ` -metadata title="${title.replace(/"/g, '\\"')}"`;
    if (artist) metaFlags += ` -metadata artist="${artist.replace(/"/g, '\\"')}"`;
    if (album)  metaFlags += ` -metadata album="${album.replace(/"/g, '\\"')}"`;
    if (year)   metaFlags += ` -metadata date="${year}"`;

    execSync(`ffmpeg -i "${processingPath}" -c copy${metaFlags} "${outputPath}" -y 2>&1`);

  } catch(e) {
    try {
      execSync(`cp "${processingPath}" "${outputPath}"`);
    } catch(e2) {
      results.push({ json: { originalName, status: 'failed', error: e2.message }});
      continue;
    }
  }

  results.push({ json: {
    originalName,
    outputPath,
    title,
    artist,
    album,
    year,
    fingerprintStatus,
    status: 'complete'
  }});
}

return results;

const { execSync, execFileSync } = require('child_process');
const fs = require('fs');

const copied = $('Move to Processing').all();

const results = [];

for (const [i, item] of $input.all().entries()) {
  const { originalName, outputPath, title, artist, album, year, fingerprintStatus, status } = item.json;

  // Clean up all temp files for this song
  try {
    const safeName = originalName.replace(/[^a-zA-Z0-9._-]/g, '_');
    execSync(`find /music/processing -name "*${safeName}*" -delete 2>/dev/null || true`);
  } catch(e) {}

  // Keep the original: only once the output file is real audio, move it from input/ to originals/.
  // When in doubt the file counts as failed and the original stays in input/.
  let original = 'left in input/';
  let finalStatus = 'failed';
  let failReason = status === 'complete' ? 'could not match original' : 'output not written';
  const source = copied[i]?.json;
  if (status === 'complete' && source?.originalName === originalName && source.originalPath) {
    let audioCheck;
    try {
      const streams = execFileSync('ffprobe', ['-v', 'error', '-select_streams', 'a', '-show_entries', 'stream=codec_type', '-of', 'csv=p=0', outputPath], { timeout: 60000, stdio: 'pipe' }).toString();
      audioCheck = streams.includes('audio') ? 'audio' : 'no_audio';
    } catch(e) {
      // ffprobe read the file but it is not audio at all
      audioCheck = String(e.stderr || '').includes('Invalid data found when processing input') ? 'no_audio' : 'check_error';
    }

    if (audioCheck === 'audio') {
      try {
        let keptPath = `/music/originals/${originalName}`;
        if (fs.existsSync(keptPath)) keptPath = `/music/originals/${Date.now()}_${originalName}`;
        execFileSync('mv', ['-n', source.originalPath, keptPath]);
        original = `kept in ${keptPath}`;
        finalStatus = 'complete';
      } catch(e) {
        failReason = 'could not move original';
      }
    } else if (audioCheck === 'no_audio') {
      // Only ever delete the bad output file, never anything in input/ or originals/
      failReason = 'not an audio file';
      try {
        if (outputPath.startsWith('/music/output/')) fs.unlinkSync(outputPath);
      } catch(e) {}
    } else {
      failReason = 'audio check failed';
    }
  }

  // Write to log file
  const timestamp = new Date().toISOString();
  const metadataFound = fingerprintStatus === 'matched';

  const logLine = finalStatus === 'failed'
    ? `[${timestamp}] FAILED | ${originalName} | Reason: ${failReason} | Original left in input/`
    : metadataFound
    ? `[${timestamp}] SUCCESS | ${originalName} | Title: ${title} | Artist: ${artist} | Album: ${album} | Year: ${year}`
    : `[${timestamp}] PROCESSED (no metadata) | ${originalName} | Reason: ${fingerprintStatus} | Needs manual tagging`;

  try {
    execSync(`echo ${JSON.stringify(logLine)} >> /music/output/processing_log.txt`);
  } catch(e) {}

  results.push({ json: {
    originalName,
    status: finalStatus,
    metadataFound,
    original,
    message: finalStatus === 'failed'
      ? `✗ Failed (${failReason}): ${originalName}, original left in input/`
      : metadataFound
      ? `✓ ${title} by ${artist}`
      : `✓ Processed (no metadata): ${originalName}`
  }});
}

return results;
